contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 h, uint blocksAhead) public payable {
        require(address(this).balance >= 1 ether, "need ether");

        // First, a fresh caller (no active guess) calls settle: must revert.
        bool noGuessReverted;
        try c.settle() { noGuessReverted = false; } catch { noGuessReverted = true; }

        // Lock in a guess with exactly 1 ether.
        c.lockInGuess{value: 1 ether}(h);

        // Immediately after locking, the target block is block.number + 1,
        // so settle() must revert because block.number is not yet greater.
        bool earlyReverted;
        try c.settle() { earlyReverted = false; } catch { earlyReverted = true; }

        // Advance chain by setting a large number of blocks through repeated no-op txs
        // in the test harness; here we param blocksAhead only to document expectation.
        // We cannot directly advance block.number, so we drive the post-target path
        // by performing blocksAhead dummy state-changing calls on c that each roll
        // the block forward one-by-one. Use lockInGuess on other addresses as no-op
        // (it reverts) but still consumes gas and stays within a single tx in the
        // checker's model: instead, we assert the pre-target rule only when the
        // target has not yet passed, and the post-target rule after it has.

        // Determine current block relative to the locked guess: the getter of the
        // public mapping returns (block, guess).
        (uint lockedBlock, bytes32 lockedGuess) = c.guesses(address(this));

        // After the early settle attempt (which must have reverted, leaving the
        // guess active), the stored target block must still be > current block,
        // i.e., the target is in the future relative to the early attempt.
        // If the checker's environment allows block.number > lockedBlock, then
        // settle() must succeed; otherwise it must revert. These two cases are
        // mutually exclusive and exhaustive.
        if (block.number > lockedBlock) {
            bool lateReverted;
            try c.settle() { lateReverted = false; } catch { lateReverted = true; }
            assert(!lateReverted);
        } else {
            assert(earlyReverted);
        }

        // General invariant: after a successful settle, the guess is cleared and
        // the caller receives 2 ether, so the test contract's balance must have
        // increased by 1 ether relative to before locking (paid 1, received 2).
        // We assert the state-clearing and the not-both-active-and-reverted rules.
        (uint finalBlock, bytes32 finalGuess) = c.guesses(address(this));
        if (!earlyReverted || block.number > lockedBlock) {
            // If settle succeeded, guess must be cleared (block == 0, guess == 0).
            assert(finalBlock == 0 || earlyReverted);
        }
    }

    receive() external payable {}
}

