            pendingGuess = hash1;
        } else if (!secondReverted) {
            pendingBlock = block.number + 1;
            pendingGuess = hash2;
        }

        assert(
            (firstReverted == (amount1 != 1 ether)) &&
            (secondReverted == (amount2 != 1 ether || !firstReverted)) &&
            (!firstReverted || !secondReverted ? (pendingBlock == block.number + 1 && pendingGuess == hash1) : (pendingBlock == block.number + 1 && pendingGuess == hash2))
        );
    }

    receive() external payable {}
}

